USE ROLE ACCOUNTADMIN;

CREATE WAREHOUSE IF NOT EXISTS YT_WH
    WAREHOUSE_SIZE = 'XSMALL'
    AUTO_SUSPEND = 60
    AUTO_RESUME = TRUE
    INITIALLY_SUSPENDED = TRUE;


CREATE DATABASE IF NOT EXISTS YOUTUBE_DB;
CREATE SCHEMA IF NOT EXISTS YOUTUBE_DB.RAW;
CREATE SCHEMA IF NOT EXISTS YOUTUBE_DB.STAGING;
CREATE SCHEMA IF NOT EXISTS YOUTUBE_DB.MARTS;

CREATE ROLE IF NOT EXISTS LOADER;        -- Python: writes RAW
CREATE ROLE IF NOT EXISTS TRANSFORMER;   -- dbt: reads RAW, writes STAGING and MARTS
CREATE ROLE IF NOT EXISTS REPORTER;      -- Power BI: reads MARTS only

GRANT USAGE ON WAREHOUSE YT_WH TO ROLE LOADER;
GRANT USAGE ON WAREHOUSE YT_WH TO ROLE TRANSFORMER;
GRANT USAGE ON WAREHOUSE YT_WH TO ROLE REPORTER;

GRANT USAGE ON DATABASE YOUTUBE_DB TO ROLE LOADER;
GRANT USAGE ON DATABASE YOUTUBE_DB TO ROLE TRANSFORMER;
GRANT USAGE ON DATABASE YOUTUBE_DB TO ROLE REPORTER;

-- LOADER: create and write tables in RAW
GRANT USAGE, CREATE TABLE ON SCHEMA YOUTUBE_DB.RAW TO ROLE LOADER;
GRANT SELECT, INSERT, DELETE ON ALL TABLES IN SCHEMA YOUTUBE_DB.RAW TO ROLE LOADER;
GRANT SELECT, INSERT, DELETE ON FUTURE TABLES IN SCHEMA YOUTUBE_DB.RAW TO ROLE LOADER;

-- TRANSFORMER: read RAW, own STAGING and MARTS
GRANT USAGE ON SCHEMA YOUTUBE_DB.RAW TO ROLE TRANSFORMER;
GRANT SELECT ON ALL TABLES IN SCHEMA YOUTUBE_DB.RAW TO ROLE TRANSFORMER;
GRANT SELECT ON FUTURE TABLES IN SCHEMA YOUTUBE_DB.RAW TO ROLE TRANSFORMER;
GRANT ALL PRIVILEGES ON SCHEMA YOUTUBE_DB.STAGING TO ROLE TRANSFORMER;
GRANT ALL PRIVILEGES ON SCHEMA YOUTUBE_DB.MARTS TO ROLE TRANSFORMER;

-- REPORTER: read-only on MARTS
GRANT USAGE ON SCHEMA YOUTUBE_DB.MARTS TO ROLE REPORTER;
GRANT SELECT ON ALL TABLES IN SCHEMA YOUTUBE_DB.MARTS TO ROLE REPORTER;
GRANT SELECT ON FUTURE TABLES IN SCHEMA YOUTUBE_DB.MARTS TO ROLE REPORTER;


CREATE USER IF NOT EXISTS YT_PIPELINE
    TYPE = SERVICE
    DEFAULT_ROLE = LOADER
    DEFAULT_WAREHOUSE = YT_WH
    RSA_PUBLIC_KEY = '';
GRANT ROLE LOADER TO USER YT_PIPELINE;
GRANT ROLE TRANSFORMER TO USER YT_PIPELINE;

CREATE USER IF NOT EXISTS YT_REPORTER
    TYPE = SERVICE
    DEFAULT_ROLE = REPORTER
    DEFAULT_WAREHOUSE = YT_WH
    RSA_PUBLIC_KEY = '';
GRANT ROLE REPORTER TO USER YT_REPORTER;

SHOW GRANTS TO ROLE LOADER;
DESC USER YT_PIPELINE;

